/**
 * Seeds the test accounts straight into the e2e database.
 *
 * - landlord: onboarding done, 1 property, 1 tenant, 1 active contract and a
 *   few payments (two paid, one late, one upcoming).
 * - onboarding: a fresh account per browser project that still has to go
 *   through the onboarding wizard.
 *
 * Passwords come from e2e/.env.e2e.local (generated by scripts/init-env.sh)
 * and are hashed with bcrypt at the same cost the app uses. Nothing secret is
 * logged.
 *
 * Usage: tsx src/seed.ts [project ...]
 */
import { randomUUID } from "node:crypto";
import bcrypt from "bcrypt";
import mysql from "mysql2/promise";
import { loadConfig, onboardingEmailFor, PROJECT_NAMES } from "./lib/config";

const SALT_ROUNDS = 12;

function isoDate(d: Date): string {
  return d.toISOString().slice(0, 10);
}

function monthsFromNow(months: number, day = 1): string {
  const now = new Date();
  return isoDate(new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() + months, day)));
}

async function upsertUser(
  db: mysql.Connection,
  opts: { email: string; password: string; name: string; onboardingComplete: boolean }
): Promise<{ id: string; created: boolean }> {
  const hash = await bcrypt.hash(opts.password, SALT_ROUNDS);
  const [rows] = await db.query<mysql.RowDataPacket[]>("SELECT id FROM users WHERE email = ?", [
    opts.email,
  ]);
  if (rows[0]) {
    await db.query(
      "UPDATE users SET password_hash = ?, onboarding_complete = ?, onboarding_step = ? WHERE id = ?",
      [hash, opts.onboardingComplete, opts.onboardingComplete ? 5 : 1, rows[0].id]
    );
    return { id: String(rows[0].id), created: false };
  }
  const id = randomUUID();
  await db.query(
    `INSERT INTO users (id, name, email, password_hash, locale, onboarding_step, onboarding_complete, landlord_type)
     VALUES (?, ?, ?, ?, 'en', ?, ?, 'individual')`,
    [id, opts.name, opts.email, hash, opts.onboardingComplete ? 5 : 1, opts.onboardingComplete]
  );
  return { id, created: true };
}

async function seedLandlordData(db: mysql.Connection, ownerId: string): Promise<void> {
  const [existing] = await db.query<mysql.RowDataPacket[]>(
    "SELECT COUNT(*) AS n FROM properties WHERE owner_id = ?",
    [ownerId]
  );
  if (Number(existing[0]?.n) > 0) return;

  const propertyId = randomUUID();
  await db.query(
    `INSERT INTO properties (id, owner_id, name, type, street, street_number, postal_code, city, country)
     VALUES (?, ?, 'Teststraat 1', 'apartment', 'Teststraat', '1', '1000', 'Brussel', 'BE')`,
    [propertyId, ownerId]
  );

  const tenantId = randomUUID();
  await db.query(
    `INSERT INTO tenants (id, owner_id, first_name, last_name, email, phone, language)
     VALUES (?, ?, 'Tess', 'Tester', 'tenant@e2e.local', '+32470000000', 'nl')`,
    [tenantId, ownerId]
  );

  const leaseId = randomUUID();
  const start = monthsFromNow(-3, 1);
  await db.query(
    `INSERT INTO leases (id, owner_id, property_id, type, region, status, signing_date, start_date,
       monthly_rent, base_rent, monthly_charges, deposit, payment_day, payment_method,
       indexation_enabled, indexation_base_month, prior_payments_settled)
     VALUES (?, ?, ?, 'residential_long', 'brussels', 'active', ?, ?, '850.00', '850.00', '50.00',
       '1700.00', 1, 'bank_transfer', 1, ?, 1)`,
    [leaseId, ownerId, propertyId, start, start, start.slice(0, 7)]
  );
  await db.query("INSERT INTO lease_tenants (lease_id, tenant_id, is_primary) VALUES (?, ?, 1)", [
    leaseId,
    tenantId,
  ]);

  const payments: Array<{ due: string; status: string; paid: string | null }> = [
    { due: monthsFromNow(-2), status: "paid", paid: monthsFromNow(-2, 2) },
    { due: monthsFromNow(-1), status: "paid", paid: monthsFromNow(-1, 3) },
    { due: monthsFromNow(0), status: "pending", paid: null },
    { due: monthsFromNow(1), status: "pending", paid: null },
  ];
  for (const p of payments) {
    await db.query(
      `INSERT INTO payments (id, lease_id, status, amount, due_date, paid_date, method, rent_amount, charges_amount)
       VALUES (?, ?, ?, '900.00', ?, ?, 'bank_transfer', '850.00', '50.00')`,
      [randomUUID(), leaseId, p.status, p.due, p.paid]
    );
  }
}

export async function seed(projects: readonly string[]): Promise<void> {
  const cfg = loadConfig();
  if (cfg.remote) {
    throw new Error("Refusing to seed in remote mode: create the accounts on that instance by hand.");
  }
  const db = await mysql.createConnection({
    host: cfg.db.host,
    port: cfg.db.port,
    user: cfg.db.user,
    password: cfg.db.password,
    database: cfg.db.name,
    timezone: "Z",
  });
  try {
    const landlord = await upsertUser(db, {
      email: cfg.landlord.email,
      password: cfg.landlord.password,
      name: "Lena Landlord",
      onboardingComplete: true,
    });
    await seedLandlordData(db, landlord.id);
    console.log(`[Seed] landlord account ready (${cfg.landlord.email})`);

    const emails = [cfg.onboarding.email, ...projects.map((p) => onboardingEmailFor(cfg, p))];
    for (const email of emails) {
      await upsertUser(db, {
        email,
        password: cfg.onboarding.password,
        name: "",
        onboardingComplete: false,
      });
      console.log(`[Seed] onboarding account ready (${email})`);
    }
  } finally {
    await db.end();
  }
}

const isMain = process.argv[1]?.endsWith("seed.ts");
if (isMain) {
  const args = process.argv.slice(2);
  seed(args.length ? args : PROJECT_NAMES).catch((err: unknown) => {
    console.error("[Seed] failed:", err instanceof Error ? err.message : err);
    process.exit(1);
  });
}
